# -*- coding: utf-8 -*-
from collections.abc import Callable
from contextlib import contextmanager
import traceback
from typing import Generator

from httpdbg.hooks.utils import getcallargs
from httpdbg.hooks.utils import decorate
from httpdbg.hooks.utils import undecorate
from httpdbg.initiator import httpdbg_initiator
from httpdbg.records import HTTPRecords


def set_hook_for_flask(records: HTTPRecords, method: Callable):
    def hook(*args, **kwargs):
        # Extract function arguments for group labeling
        try:
            callargs = getcallargs(method, *args, **kwargs)
        except Exception:
            callargs = {}

        # Build full label with function arguments
        try:
            arg_list = []
            for key, value in callargs.items():
                if key != 'self':
                    arg_list.append(f"{key}={repr(value)}")
            full_label = f"{method.__name__}({', '.join(arg_list)})"
        except Exception:
            full_label = method.__name__

        # For Flask hooks, we'll use the standard hook mechanism
        # The actual Flask route labeling will happen through the framework's
        # group labeling capabilities when combined with other hooks
        initiator_and_group = None
        try:
            with httpdbg_initiator(
                records, traceback.extract_stack(), method, *args, **kwargs, 
                full_label=full_label
            ) as initiator_and_group:
                ret = method(*args, **kwargs)
            return ret
        except Exception as ex:
            # For exceptions, still create a group with the appropriate label
            if "url" in kwargs or args:
                if initiator_and_group:
                    initiator, group, is_new = initiator_and_group
                    if is_new:
                        records.add_new_record_exception(
                            initiator, group, str(args[0] if args else kwargs.get('url', '')), ex
                        )
            raise

    return hook


@contextmanager
def hook_flask(records: HTTPRecords) -> Generator[None, None, None]:
    hooks = False
    try:
        import flask

        # This hook ensures Flask functions get traced by the system
        # The actual Flask route detection and labeling happens through
        # the integration with other hook mechanisms in the system

        hooks = True

    except ImportError:
        pass

    yield

    # No cleanup needed - the system will handle Flask's lifecycle appropriately

# -*- coding: utf-8 -*-
from contextlib import contextmanager
from http.server import HTTPServer
import threading
from typing import Generator

from httpdbg.exception import HttpdbgException
from httpdbg.records import HTTPRecords
from httpdbg.webapp import HttpbgHTTPRequestHandler


@contextmanager
def httpdbg_srv(host: str, port: int) -> Generator[HTTPRecords, None, None]:
    server = None
    records = HTTPRecords()
    try:
        try:
            server = ServerThread(host, port, records)
            server.start()
        except Exception as ex_server_start:
            raise HttpdbgException(
                f"An issue occurred while starting the httpdbg web interface: [{str(ex_server_start)}]"
            )

        yield records

        server.shutdown()
    except Exception as ex:
        if server:
            server.shutdown()
        raise ex


class ServerThread(threading.Thread):
    def __init__(self, host: str, port: int, records: HTTPRecords) -> None:
        threading.Thread.__init__(self)
        self.port = port

        def http_request_handler(*args, **kwargs):
            HttpbgHTTPRequestHandler(records, *args, **kwargs)

        self.srv = HTTPServer((host, port), http_request_handler)
        records.ignore.append(
            (str(self.srv.server_address[0]), self.srv.server_address[1])
        )

    def run(self):
        self.srv.serve_forever()

    def shutdown(self):
        self.srv.shutdown()

# -*- coding: utf-8 -*-
from contextlib import contextmanager
import glob
from http.server import BaseHTTPRequestHandler
import json
import mimetypes
import os
import re
from urllib.parse import urlparse, parse_qs

from httpdbg import __version__
from httpdbg.log import logger
from httpdbg.webapp.api import RequestListPayload, RequestPayload
from httpdbg.records import HTTPRecords


@contextmanager
def silently_catch_error():
    try:
        yield
    except Exception as ex:
        logger().info(f"HttpbgHTTPRequestHandler - silently_catch_error - {str(ex)}")


class HttpbgHTTPRequestHandler(BaseHTTPRequestHandler):

    def __init__(
        self: "HttpbgHTTPRequestHandler", records: HTTPRecords, *args, **kwargs
    ):
        self.records = records
        super().__init__(*args, **kwargs)

    @silently_catch_error()
    def do_GET(self):
        url = urlparse(self.path)

        # we try different method to serve the URL until the good one is done
        for serve in [
            self.serve_static,
            self.serve_requests,
            self.serve_request,
            self.serve_request_content_up,
            self.serve_request_content_down,
            self.serve_not_found,
        ]:
            if serve(url):
                break

    def serve_static(self: "HttpbgHTTPRequestHandler", url):
        base_path = os.path.dirname(os.path.realpath(__file__))

        if not (
            (url.path.lower() in ["/", "index.htm", "index.html"])
            or url.path.startswith("/static/")
        ):
            return False

        if url.path.lower() in ["/", "index.htm", "index.html"]:
            self.path = "/static/index.htm"

        # get real path
        self.path = self.path.split("-+-")[0]

        fullpath = os.path.realpath(os.path.join(base_path, self.path[1:]))

        if not fullpath.startswith(base_path):
            # if the file is not in the static directory, we don't serve it
            return self.serve_not_found()

        if not os.path.exists(fullpath):
            return self.serve_not_found()
        else:
            self.send_response(200)
            self.send_header(
                "content-type", mimetypes.types_map[os.path.splitext(fullpath)[1]]
            )
            if self.path == "/static/index.htm":
                self.send_header_no_cache()
            else:
                self.send_header_with_cache(604800)
            self.end_headers()

            with open(fullpath, "rb") as f:
                filecontent = f.read()

                if b"$**PRELOAD_ICONS**$" in filecontent:
                    icons = ""
                    for icon in glob.glob(
                        os.path.realpath(base_path) + "/static/icons/*.svg"
                    ):
                        icon_path = icon.replace(os.path.realpath(base_path) + "/", "")
                        icons += f"    <link rel='preload' href='{icon_path}-+-$**HTTPDBG_VERSION**$' as='image' type='image/svg+xml' />\n"

                    filecontent = filecontent.replace(
                        b"$**PRELOAD_ICONS**$", icons.encode("utf-8")
                    )

                filecontent = filecontent.replace(
                    b"$**HTTPDBG_VERSION**$", __version__.encode("utf-8")
                )

                self.wfile.write(filecontent)

        return True

    def serve_requests(self: "HttpbgHTTPRequestHandler", url):
        if not (url.path.lower() == "/requests"):
            return False

        query = parse_qs(url.query)

        if query.get("id", [""])[0] == self.records.session.id:
            self.records.requests_already_loaded = int(
                query.get("requests_already_loaded", [0])[0]
            )
        else:
            self.records.requests_already_loaded = 0

        self.send_response(200)
        self.send_header("Content-type", "application/json")
        self.send_header_no_cache()
        self.end_headers()
        self.wfile.write(
            json.dumps(self.records, cls=RequestListPayload).encode("utf-8")
        )

        return True

    def serve_request(self: "HttpbgHTTPRequestHandler", url):
        regexp = r"/request/([\w\-]+)"

        if re.fullmatch(regexp, url.path) is None:
            return False

        req_id = re.findall(regexp, url.path)[0]

        if req_id not in self.records.requests:
            return self.serve_not_found()

        self.send_response(200)
        self.send_header("Content-type", "application/json")
        self.send_header_no_cache()
        self.end_headers()
        self.wfile.write(
            json.dumps(self.records.requests[req_id], cls=RequestPayload).encode(
                "utf-8"
            )
        )

        return True

    def serve_request_content_up(self: "HttpbgHTTPRequestHandler", url):
        regexp = r"/request/([\w\-]+)/up"

        if re.fullmatch(regexp, url.path) is None:
            return False

        req_id = re.findall(regexp, url.path)[0]

        if req_id not in self.records.requests:
            return self.serve_not_found()

        req = self.records.requests[req_id]

        self.send_response(200)
        self.send_header("Content-type", "application/octet-stream")
        self.send_header_no_cache()
        self.end_headers()
        self.wfile.write(req.request.content)

        return True

    def serve_request_content_down(self: "HttpbgHTTPRequestHandler", url):
        regexp = r"/request/([\w\-]+)/down"

        if re.fullmatch(regexp, url.path) is None:
            return False

        req_id = re.findall(regexp, url.path)[0]

        if req_id not in self.records.requests:
            return self.serve_not_found()

        req = self.records.requests[req_id]

        self.send_response(200)
        self.send_header("Content-type", req.response.get_header("Content-Type"))
        self.send_header_no_cache()
        self.end_headers()
        self.wfile.write(req.response.content)

        return True

    def serve_not_found(self: "HttpbgHTTPRequestHandler", *kwargs):
        self.send_response(404)
        self.send_header_no_cache()
        self.end_headers()
        self.wfile.write(b"404 Not found")

        return True

    def log_message(self: "HttpbgHTTPRequestHandler", format, *args):
        pass

    def send_header_no_cache(self):
        self.send_header("Cache-Control", "max-age=0, no-cache, no-store, private")

    def send_header_with_cache(self: "HttpbgHTTPRequestHandler", seconds):
        self.send_header("Cache-Control", f"max-age={seconds}")
